  --foreground: #ebe4d6;
  --card: #423c31;
  --card-foreground: #ebe4d6;
  --popover: #423c31;
  --popover-foreground: #ebe4d6;
  --primary: #8aa17a;
  --primary-foreground: #2a2522;
  --secondary: #585246;
  --secondary-foreground: #ebe4d6;
  --muted: #4a4439;
  --muted-foreground: #a9a094;
  --accent: #9f8e5d;
  --accent-foreground: #2a2522;
  --destructive: #b4776b;
  --destructive-foreground: #f1eadc;
  --border: #585246;
  --input: #585246;
  --ring: #8aa17a;
  --chart-1: #8aa17a;
  --chart-2: #9bb089;
  --chart-3: #6f8568;
  --chart-4: #9f8e5d;
  --chart-5: #5e6f58;
  --radius: 0.425rem;
  --sidebar: #3a352a;
  --sidebar-foreground: #ebe4d6;
  --sidebar-primary: #8aa17a;
  --sidebar-primary-foreground: #2a2522;
  --sidebar-accent: #9f8e5d;
  --sidebar-accent-foreground: #2a2522;
  --sidebar-border: #585246;
  --sidebar-ring: #8aa17a;
  --font-sans: Merriweather, serif;
